#include <vector>
#include <cstddef>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    int parity = 0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for reduction(^: parity)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        parity ^= static_cast<int>(x[static_cast<std::size_t>(i)]);
    }

    return parity != 0;
}
